CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE,email TEXT UNIQUE,password_hash TEXT,display_name TEXT,bio TEXT DEFAULT '',created_at INTEGER);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,csrf TEXT,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,expires_at INTEGER);
CREATE TABLE IF NOT EXISTS videos(id TEXT PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,title TEXT,description TEXT DEFAULT '',category TEXT,filename TEXT,poster TEXT DEFAULT '',duration REAL DEFAULT 1,size INTEGER DEFAULT 1000,views INTEGER DEFAULT 0,created_at INTEGER);
CREATE TABLE IF NOT EXISTS likes(user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,video_id TEXT REFERENCES videos(id) ON DELETE CASCADE,PRIMARY KEY(user_id,video_id));
CREATE TABLE IF NOT EXISTS comments(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,video_id TEXT REFERENCES videos(id) ON DELETE CASCADE,body TEXT,created_at INTEGER);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,count INTEGER,expires_at INTEGER);
